#!/bin/sh
# ============================================================================
#  build.sh — rebuild the DOS-extender LE/LX fixtures in ../../fixtures/
#
#  Toolchain: Open Watcom v2 (verified with "Version 2.0 beta Oct 19 2026",
#  Linux host, installed in /opt/watcom). Override with WATCOM=/path/to/watcom.
#
#  Run from anywhere — all paths are resolved relative to this file. Objects
#  and intermediate images go to ./build/, the fixtures are copied to
#  ../../fixtures/, and MANIFEST.txt (next to this script) records the
#  toolchain version plus the size and sha256 of every produced file.
#
#  Licensing of the results (see ../..:/license-*):
#    - the extender code embedded by `option stub=` is covered by
#      license-dos4gw (Tenberry/OW royalty-free note) and license-dos32a
#      (BSD-style, requires the acknowledgment "This product uses DOS/32
#      Advanced DOS Extender technology." — the DOS32A tests print it);
#    - the compiled images as a whole: license-openwatcom;
#    - never commit DOS4GW.EXE or DOS32A.EXE themselves — only the images
#      that wlink produced from these sources.
# ============================================================================
set -eu

WATCOM="${WATCOM:-/opt/watcom}"
export WATCOM
# One assignment per export statement. `export WATCOM=… PATH="$WATCOM/binl64:…"`
# on a single line does not yet see the new WATCOM and silently produces
# PATH=/binl64:…, which shows up as "wcc386: command not found".
export PATH="$WATCOM/binl64:$PATH"
export INCLUDE="$WATCOM/h"
export LIBS="$WATCOM/lib386"

src=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
build="$src/build"
fixtures="$src/../../fixtures"

mkdir -p "$build"
rm -f "$build"/*.obj "$build"/*.exe
cd "$build"

# --- compile (32-bit flat, no optimization noise, quiet) ------------------
wcc386 -bt=dos4g  -zq -ox -fo=hello_dos4g.obj "$src/hello.c"
wcc386 -bt=dos32a -zq -ox -fo=hello_dos32a.obj "$src/hello.c"
wcc386 -bt=os2    -zq -ox -fo=hello_os2.obj    "$src/hello.c"
wcc386 -bt=dos4g  -zq -ox -fo=many_dos4g.obj   "$src/many.c"
wcc386 -bt=dos4g  -zq -ox -fo=big_dos4g.obj    "$src/big.c"

# --- link -----------------------------------------------------------------
# The DOS-8.3 output name is what lands in the LE header's module-name field,
# so the names below are load-bearing; the descriptive file name is applied by
# the copy step. `option stub=<extender>` is what makes an image *bound*.
wlink option quiet system dos4g  file hello_dos4g.obj  name d4gunbnd.exe
wlink option quiet system dos4g  option stub="$WATCOM/binw/dos4gw.exe" \
      file hello_dos4g.obj name d4gbound.exe
wlink option quiet system dos32a file hello_dos32a.obj name d3aunbnd.exe
wlink option quiet system dos32a option stub="$WATCOM/binw/dos32a.exe" \
      file hello_dos32a.obj name d3abound.exe
wlink option quiet system os2v2  file hello_os2.obj    name os2lx.exe
wlink option quiet system dos4g  file many_dos4g.obj   name manypge.exe
wlink option quiet system dos4g  file big_dos4g.obj    name bigbss.exe

# --- publish as fixtures --------------------------------------------------
cp d4gunbnd.exe  "$fixtures/dos4gw-unbound.BIN"
cp d4gbound.exe  "$fixtures/dos4gw-bound.BIN"
cp d3aunbnd.exe  "$fixtures/dos32a-unbound.BIN"
cp d3abound.exe  "$fixtures/dos32a-bound.BIN"
cp os2lx.exe     "$fixtures/os2-lx.BIN"
cp manypge.exe   "$fixtures/many-pages.BIN"
cp bigbss.exe    "$fixtures/big-bss.BIN"

# --- manifest -------------------------------------------------------------
{
    echo "# Regenerated by build.sh — do not edit by hand."
    echo "# Toolchain: $(wlink /v 2>&1 | sed -n '1p')"
    echo "# Format: <sha256> <bytes> <fixture>"
    for f in dos4gw-unbound dos4gw-bound dos32a-unbound dos32a-bound os2-lx \
             many-pages big-bss; do
        p="$fixtures/$f.BIN"
        printf '%s %s %s\n' "$(sha256sum "$p" | cut -d' ' -f1)" \
            "$(wc -c < "$p")" "$f.BIN"
    done
} > "$src/MANIFEST.txt"

cat "$src/MANIFEST.txt"
